/* The record GetFileKeySize reads: a file key {first sector, size, kind} as bas.cpp's CDFILE and tu_1848A8.cpp's
   SECTORKEY lay it out (kind 2: a file on the disc). */
struct CDREQ
{
      int sector;               /* +0x0 */
      int size;                 /* +0x4 bytes */
      int kind;                 /* +0x8 2 = disc file */
};

extern int D_002BD4C0;
extern const char D_002A4EF0[] = "fid:#unknown";

